import{_ as o,o as e,c as i,a2 as t}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/assets/%E5%B7%A5%E4%BD%9C%E5%8F%B0.CkTfQk0e.png",h=JSON.parse('{"title":"移动端 IoT 物联网","description":"","frontmatter":{},"headers":[],"relativePath":"iot/mobile.md","filePath":"iot/mobile.md","lastUpdated":null}'),r={name:"iot/mobile.md"};function d(c,a,n,s,u,p){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="移动端-iot-物联网" tabindex="-1">移动端 IoT 物联网 <a class="header-anchor" href="#移动端-iot-物联网" aria-label="Permalink to &quot;移动端 IoT 物联网&quot;">​</a></h1><p>友情提示</p><p>本文讲解 yudao 移动端（uni-app 版）的 IoT 物联网，重点说清楚两件事：IoT 模块<strong>已经提供手机端</strong>、当前支持的<strong>主要功能</strong>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a>，基于 <code>uni-app</code> + <code>Vue3</code> + <code>wot-ui</code> 实现，支持 H5、微信小程序等多端。</li><li>后端：复用 PC 端同一套 <code>yudao-module-iot</code> 模块与 <code>/iot/**</code> 接口，移动端只是换了一层 UI。</li></ul><h2 id="_1-移动端功能" tabindex="-1">1. 移动端功能 <a class="header-anchor" href="#_1-移动端功能" aria-label="Permalink to &quot;1. 移动端功能&quot;">​</a></h2><ul><li>设备接入：产品、设备、产品分类、设备分组、产品物模型。</li><li>规则引擎：场景联动、数据流转。</li><li>告警与运维：告警配置、告警记录、OTA 固件，以及 IoT 首页统计。</li></ul><p><img src="'+l+'" alt="IoT 移动端"></p><h2 id="_2-启动与发布" tabindex="-1">2. 启动与发布 <a class="header-anchor" href="#_2-启动与发布" aria-label="Permalink to &quot;2. 启动与发布&quot;">​</a></h2><ul><li>启动：参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档的「1.4 Vue3 + uni-app 版本」小节。</li><li>发布：参考 <a href="./../admin-uniapp/deploy">《运行发布》</a> 文档。</li></ul><p>启动完成后，在工作台选择「IoT 物联网」即可进入。</p><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><ul><li>页面：<code>src/pages-iot/</code>、<code>src/pages-statistics/iot/</code></li><li>接口：<code>src/api/iot/</code></li></ul>',12)])])}const m=o(r,[["render",d]]);export{h as __pageData,m as default};
